def make_palindrome(string: str) -> str:
    """Find the shortest palindrome that begins with a supplied string."""
    if not string:
        return ""
    n = len(string)
    for i in range(n):
        suffix = string[i:]
        if suffix == suffix[::-1]:
            # prefix before suffix to be appended in reverse
            prefix_to_add = string[:i][::-1]
            return string + prefix_to_add
    # In worst case, no suffix palindrome, append whole string reversed except first char
    return string + string[:-1][::-1]

