def tri(n):
    """Return list of tribonacci numbers tri(0) to tri(n) with the custom recurrence."""
    memo = {}

    def trib(k):
        if k > n + 1:
            return 0
        if k == 0:
            return 1
        if k == 1:
            return 3
        if k in memo:
            return memo[k]
        if k % 2 == 0:  # even
            val = 1 + k // 2
        else:  # odd and > 1
            val = trib(k - 1) + trib(k - 2) + trib(k + 1)
        memo[k] = val
        return val

    return [trib(i) for i in range(n + 1)]

