def get_max_triples(n: int) -> int:
    """
    Given integer n, compute the number of triples (i<j<k) where a[i] = i^2 - i + 1,
    and sum of a[i], a[j], a[k] is divisible by 3.
    """
    c0 = 0  # count of elements with a[i] % 3 == 0 (i mod 3 == 2)
    c1 = 0  # count of elements with a[i] % 3 == 1 (i mod 3 == 0 or 1)

    for i in range(1, n+1):
        if i % 3 == 2:
            c0 += 1
        else:
            c1 += 1

    return comb(c0, 3) + comb(c1, 3)

